const main=document.querySelector('#main'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
const SINGLE_PLAYER_ONLY=document.documentElement?.dataset?.playMode==='solo';
const KEY='quantum-quest-prototype-v3',LEGACY_KEYS=['quantum-quest-prototype-v2','quantum-quest-prototype-v1'];let legacyGame=null;let game=null,screen='home',mode='solo',maxRounds=10,tab='market',filter='all',onlyAvailable=true,aiTimer=null,fast=false,saving=true,toastTimer;
