const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(cat,variant=0)=>{const base={blue:'<rect x="37" y="15" width="46" height="36" rx="4"/><rect x="47" y="24" width="26" height="18" rx="2"/><path d="M45 15V6M60 15V6M75 15V6M45 51v9M60 51v9M75 51v9M37 22H25M37 33H25M37 44H25M83 22h12M83 33h12M83 44h12"/>',red:'<path d="M60 5 85 15v17c0 14-14 23-25 29-11-6-25-15-25-29V15Z"/><path d="m49 32 8 8 15-18"/><path d="M18 17h10M14 26h10M18 45h10M92 17h10M96 26h10M92 45h10"/>',green:'<circle cx="60" cy="33" r="9"/><circle cx="60" cy="33" r="23" stroke-dasharray="3 4"/><path d="M60 2v12M60 52v12M28 33h13M79 33h13M38 11l9 9M73 46l9 9M38 55l9-9M73 20l9-9"/><circle cx="60" cy="33" r="3"/>',yellow:'<circle cx="37" cy="17" r="9"/><circle cx="81" cy="21" r="12"/><circle cx="59" cy="50" r="10"/><path d="m45 19 24 1M41 25l12 18M74 31  -9 12"/><path d="M21 40h10M26 35v10M95 48h10M100 43v10"/>'};return '<svg viewBox="0 0 120 66" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">'+base[cat]+'</svg>';};
const color=k=>k==='wild'?'#d7d5f1':catById(k)?.color;
const token=(k,n,extra='')=>'<span class="tiny-token art-token" title="'+tokenName(k)+' '+n+'個" aria-label="'+tokenName(k)+' '+n+'個">'+tokenArt(k)+'<span>'+n+'</span>'+extra+'</span>';
const tokens=p=>Object.entries(p.tokens).map(([k,n])=>token(k,n)).join('');
const isCpu=()=>game&&(game.mode==='online'?game.controllers[game.turn]==='cpu':game.mode==='solo'&&game.turn!==game.human);
const myTurn=()=>game&&(game.mode==='online'?game.turn===game.human:!isCpu());
const canAct=()=>screen==='game'&&game&&myTurn()&&game.phase==='action'&&!game.notice&&(!onlineActive||onlineStatus==='connected'&&!onlineBusy&&!onlineRoom?.pendingTrade);
function save(){if(!game||tutorialSession)return;if(onlineActive){try{localStorage.setItem(onlineNotesKey(),JSON.stringify(game.notes));}catch{}return;}try{localStorage.setItem(KEY,JSON.stringify(game));saving=true;}catch{saving=false;}}
try{const saved=JSON.parse(localStorage.getItem(KEY));if(validState(saved)&&(!SINGLE_PLAYER_ONLY||saved.mode==='solo'))game=normalizeCalendar(saved);for(const key of LEGACY_KEYS){const previous=JSON.parse(localStorage.getItem(key));if([1,2].includes(previous?.version)&&Array.isArray(previous.log)&&Array.isArray(previous.notes)){legacyGame=previous;break;}}}catch{}
let soundStorage;try{soundStorage=localStorage;}catch{}
