function updateSoundLabels(){const p=sounds.settings,label=!sounds.available?'音 未対応':!p.enabled?'音 OFF':p.volume===0?'音 0%':'音 ON';document.querySelectorAll('[data-sound-label]').forEach(el=>el.textContent=label);}
function syncSoundSettings(){const p=sounds.settings,enabled=document.querySelector('#sound-enabled'),range=document.querySelector('#sound-volume'),value=document.querySelector('#sound-volume-value'),help=document.querySelector('#sound-help');if(enabled)enabled.checked=p.enabled;if(range)range.value=Math.round(p.volume*100);if(value)value.textContent=Math.round(p.volume*100)+'%';document.querySelectorAll('[data-sound-state]').forEach(el=>el.textContent=p.enabled?'ON':'OFF');document.querySelectorAll('[data-action="sound-sample"]').forEach(el=>el.disabled=!sounds.available||!p.enabled||p.volume===0);if(help)help.textContent=!sounds.available?'このブラウザでは効果音を再生できません。':!p.enabled?'効果音はオフです。':p.volume===0?'音量が0です。スライダーで調整できます。':'下のボタンで音を試せます。';updateSoundLabels();}
function showSoundSettings(){clearTimeout(aiTimer);sounds.stop();soundDialog.innerHTML=soundSettingsMarkup(sounds);if(!soundDialog.open)soundDialog.showModal();syncSoundSettings();}
function closeSoundSettings(){sounds.stop();soundDialog.close();}
function previewSound(kind){sounds.unlock().then(()=>sounds.play(kind)).then(ok=>{if(!ok&&sounds.settings.enabled&&sounds.settings.volume>0&&sounds.available){const help=document.querySelector('#sound-help');if(help)help.textContent='音を再生できませんでした。もう一度お試しください。';}});}
soundDialog.addEventListener('cancel',ev=>{ev.preventDefault();closeSoundSettings();});soundDialog.addEventListener('close',()=>scheduleCpu());
// Audio starts only after a real interaction; never replay sounds missed while hidden or muted.
document.addEventListener('pointerdown',()=>sounds.unlock(),{capture:true,passive:true});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' ')sounds.unlock();},{capture:true});
document.addEventListener('click',()=>sounds.unlock(),{capture:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)sounds.stop();});
window.addEventListener('pagehide',()=>sounds.stop());
updateSoundLabels();
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function showModal(title,body,actions='',cls=''){modalKind='detail';clearTimeout(aiTimer);modal.className=cls==='catalog-view'?'wide-dialog':'';modalContent.innerHTML='<div class="modal-inner '+cls+'"><div class="modal-top"><h2 id="modal-title">'+colorText(title)+'</h2><button class="close-btn" data-action="close" aria-label="閉じる">×</button></div><div class="modal-sound-control">'+soundButton()+'</div>'+body+(actions?'<div class="modal-actions">'+actions+'</div>':'')+'</div>';if(!modal.open)modal.showModal();updateSoundLabels();syncSelectColors(document);}
function closeModal(){if(onlineActive&&modalKind==='event'&&game?.notice){if(game.notice.actor!==game.human){pauseEvent();return;}if(game.notice.type==='choice'){toast('効果の対象を選んでください。');return;}onlineAction('ack');return;}if(modalKind==='event'&&game?.notice&&screen==='game'&&!acknowledge(game)){toast('効果の対象を選んでください。');return;}modal.close();save();if(screen==='game')render();else scheduleCpu();}
modal.addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});
function home(){if(onlineActive){leaveOnlineView();return;}if(tutorialSession){exitTutorial();return;}sounds.stop();clearTimeout(aiTimer);screen='home';if(modal.open)modal.close();render();}
function render(){if(onlineActive&&(!onlineRoom?.game)){renderOnlineWaiting();return;}if(tutorialSession)updateTutorial(tutorialSession);if(eventNoticeRef!==game?.notice){eventNoticeRef=game?.notice;eventSuspended=false;eventChoiceId=null;}const cues=gameSounds.observe(game);if(screen==='game'&&cues.length)sounds.play(cues);clearTimeout(aiTimer);if(game?.phase==='finished'&&screen==='game')screen='reflection';document.querySelector('#header-status').textContent=tutorialSession?'GUIDED PRACTICE':screen==='home'?'DIGITAL PLAYGROUND':screen==='reflection'?'REFLECTION & DIALOGUE':game.mode==='online'?'ONLINE TABLE':game.mode==='solo'?'SOLO EXPERIENCE':'LOCAL TABLE / 4 PLAYERS';if(screen==='home')renderHome();else if(screen==='reflection')renderReflection();else renderBoard();if(onlineActive&&screen==='reflection')main.innerHTML=renderOnlineBar(onlineRoom,{status:onlineStatus,busy:onlineBusy})+main.innerHTML;if(screen==='game'&&game.notice&&!eventSuspended&&(!onlineActive||modalKind==='event'||!modal.open))showEvent();scheduleCpu();}
function renderHome(){if(!SINGLE_PLAYER_ONLY&&mode==='online'){main.innerHTML=renderOnlineSetup({maxRounds,recent:onlineRecent(),name:onlineName()});return;}main.innerHTML='<div class="intro">'+(SINGLE_PLAYER_ONLY?'<p class="solo-public-note">ブラウザ試遊版 · あなた1人とCPU3勢力 · ログイン不要</p>':'')+(legacyGame?'<div class="legacy-record"><span>イベントとミッションを実装しました。旧版からは新しいゲームでお試しください。以前の記録とメモは保存できます。</span><button class="text-btn" data-action="export-legacy">旧版の記録を保存 ↓</button></div>':'')+(game?'<div class="resume-line"><span>'+game.year+'年 · '+game.round+'ラウンド目の'+(game.phase==='finished'?'振り返り':'ゲーム')+'を保存しています</span><button class="text-btn" data-action="resume">続きから開く →</button></div>':'')+'<section class="hero"><div><div class="eyebrow">PLAY. DISCOVER. DISCUSS.</div><h1>未来は、まだ<br><span>決まっていない。</span></h1><p class="hero-copy">人材を集め、量子技術を開発する。<br>競争と協力の先に、どんな社会が生まれるだろう。<br>カードを手に、未来を考える旅へ。</p><div class="hero-meta"><span><b>01–04</b> PLAYERS</span><span><b>'+maxRounds+'</b> ROUNDS</span><span>専門知識は不要</span></div></div><div class="hero-art" aria-label="Quantum Questの量子創薬・FTQC・量子ガバナンス評議会カード"><div class="orbit"></div><span class="orbit-star">✧</span><img class="hero-card first" src="./assets/drug.png" alt="量子創薬のカード"><img class="hero-card last" src="./assets/qgc.png" alt="量子ガバナンス評議会のカード"><img class="hero-card middle" src="./assets/ftqc.png" alt="FTQCのカード"><span class="orbit-label">EXPLORE POSSIBLE FUTURES</span></div></section><section class="tutorial-entry"><div><h2>どんなゲーム？ カードを読みながら、体験しよう。</h2><p>ゲームの目的・カードの種類から、開発・イベント・ミッションまで。説明と練習の12ステップ。</p><small>自分のペースで読んで進められます。練習の進行は保存されません。通常プレイの保存データはそのまま残ります。</small></div><button class="primary" data-action="tutorial-start">チュートリアルを始める →</button></section><section class="setup" aria-labelledby="setup-title"><div class="setup-top"><h2 class="section-title" id="setup-title">旅の準備をしよう。<small>SET UP YOUR QUEST</small></h2><div class="segment" aria-label="プレイ方法"><button class="'+(mode==='solo'?'active':'')+'" data-action="mode" data-id="solo" aria-pressed="'+(mode==='solo')+'">シングルプレイ</button>'+(!SINGLE_PLAYER_ONLY?'<button data-action="mode" data-id="online" aria-pressed="false">マルチプレイ</button><button class="'+(mode==='table'?'active':'')+'" data-action="mode" data-id="table" aria-pressed="'+(mode==='table')+'">同じ端末で4人</button>':'')+'</div></div><div class="setup-label"><span>開始時にロールをランダム配布 · '+(mode==='solo'?'他の3勢力はCPUが担当':'プレイヤー1〜4へ1枚ずつ配布')+'</span><span class="random-deal-hint">どの未来を担うかは、カード次第。</span></div><div class="roles">'+ROLES.map(r=>'<button class="role-option role-reference" style="--cat:'+color(r.cat)+'" data-action="role-card" data-id="'+r.id+'" aria-label="'+e(r.name)+'のロールを確認"><span class="role-initial">'+r.mark+'</span><span class="role-name">'+r.name+'</span><span class="role-ja">'+r.ja+'</span><p class="role-desc">'+colorText(r.desc)+'</p><small>カードを見る ↗</small></button>').join('')+'</div><div class="setup-bottom"><div><div class="start-options"><label for="round-count" class="muted">試遊の長さ</label><select id="round-count" style="width:auto"><option value="8" '+(maxRounds===8?'selected':'')+'>8年（2041–2048）</option><option value="10" '+(maxRounds===10?'selected':'')+'>10年・10ラウンド（2041–2050／標準）</option><option value="12" '+(maxRounds===12?'selected':'')+'>12年（2041–2052）</option></select></div><p class="setup-note"><strong>ルール確認用の試作です。</strong>カードをシートへドラッグして開発できます。全'+CARDS.length+'枚のアセットと4枚のロールに原版を使用し、カード数値も反映済みです。7カード・Historic Dayの抽選と効果、ミッションの達成・報酬を実装しています。</p></div><div class="setup-actions"><button class="outline" data-action="rules">遊び方</button><button class="primary" data-action="new">体験をはじめる <span class="arrow">→</span></button></div></div></section></div>';}
function playerCard(p){const r=ROLES[p.role];return '<div class="player '+(game.turn===r.id?'current':'')+'" style="--cat:'+color(r.cat)+'"><div class="player-top"><div class="player-name">'+r.name+(game.mode==='solo'&&game.human===r.id?'<span class="solo-tag">YOU</span>':'')+'<small>'+r.ja+'</small></div><div class="player-count">'+p.assets.length+'<small>ASSETS</small></div></div><div class="token-row">'+tokens(p)+'</div><div class="owned-mini" aria-hidden="true">'+p.assets.map(id=>'<i style="--cat:'+color(cardById(id).cat)+'"></i>').join('')+'</div></div>';}
function cardHTML(c){const owner=ownedBy(game,c.id),ready=canAct()&&canBuild(game,game.turn,c.id),p=game.players[game.turn],shortage=Math.max(0,c.cost-p.tokens[c.cat]-p.tokens.wild);return '<article class="asset-card '+(owner>=0?'owned':ready?'affordable':'')+'" style="--cat:'+color(c.cat)+';--artbg:'+color(c.cat)+'65"><span class="category-line"></span><button class="asset-main" data-action="detail" data-id="'+c.id+'" aria-label="'+e(c.name)+'の詳細"><div class="asset-top"><span>'+catById(c.cat).short+'</span><span class="cost"><i class="token-dot"></i>'+c.cost+'</span></div><div class="asset-art">'+icon(c.cat)+'<small>'+c.en.split(' ')[0]+'</small></div><h3 class="asset-name">'+c.name+'</h3><div class="asset-en">'+c.en+'</div><div class="asset-rule"><div class="dice-numbers">'+c.dice.map(n=>'<span class="die-small '+(game.dice&&game.dice[0]+game.dice[1]===n?'hit':'')+'">'+n+'</span>').join('')+'</div><div class="token-row">'+Object.entries(c.yields).map(([k,n])=>token(k,n)).join('')+'</div></div></button><div class="card-action">'+(owner>=0?'<span class="asset-status">'+ROLES[owner].ja+' が所有</span>':'<button class="develop-btn '+(ready?'ready':'')+'" data-action="build" data-id="'+c.id+'" '+(!ready?'disabled':'')+'>'+(ready?'開発する ＋':shortage>0?'あと '+shortage+' 人材':game.phase==='roll'?'サイコロを振って開発':'自分の手番で開発')+'</button>')+'</div></article>';}
function renderBoard(){
 if(matSeat===null || (!matPinned && lastRenderedTurn!==game.turn))matSeat=game.mode==='solo'||game.mode==='online'?game.human:game.turn;
 lastRenderedTurn=game.turn;
 const oldLog=document.querySelector('.activity-scroll'),logScroll=oldLog?{top:oldLog.scrollTop,height:oldLog.scrollHeight}:null;
 main.innerHTML=(onlineActive?renderOnlineBar(onlineRoom,{status:onlineStatus,busy:onlineBusy}):'')+(tutorialSession?'<div class="tutorial-mode" data-lesson="'+tutorialLesson(tutorialSession).id+'">'+renderTutorialCoach(tutorialSession):'')+(eventSuspended&&game.notice?'<div class="event-resume-bar"><p>'+colorText(effectById(game.notice.cardId)?.title||game.notice.title)+'<small>効果の選択を保留中です。カードやシートを確認できます。</small></p><button class="primary" data-action="resume-event">選択画面に戻る →</button></div>':'')+renderTabletop(game,{sheetChanges:sheetTracker.observe(game),selectedId,matSeat,canAct:canAct()&&!rolling&&!interactionBusy,humanTurn:myTurn()&&(!onlineActive||onlineStatus==='connected'&&!onlineBusy&&!onlineRoom?.pendingTrade),busy:rolling||interactionBusy,rolling,fast,saving,logFilter,canFinish:!onlineActive||onlineRoom?.isHost,tutorial:!!tutorialSession,canBuildCard:id=>!tutorialSession||tutorialAllows(tutorialSession,'build',id),canRoll:!tutorialSession||tutorialAllows(tutorialSession,'roll'),canExchange:!tutorialSession||tutorialAllows(tutorialSession,'exchange')})+(tutorialSession?'</div>':'');
 const nextLog=document.querySelector('.activity-scroll');if(nextLog&&logScroll?.top>4)nextLog.scrollTop=logScroll.top+nextLog.scrollHeight-logScroll.height;
}

function showDetail(id){const c=cardById(id);if(!c)return;const owner=game?ownedBy(game,id):-1,ready=game&&canAct()&&(!tutorialSession||tutorialAllows(tutorialSession,'build',id))&&developmentView(game,id,{busy:rolling||interactionBusy}).ready;showModal(c.name,(c.art?'<div class="original-card-preview">'+renderFlippableCard({src:'./assets/'+c.art,title:c.name,group:'asset',portrait:true})+'<p class="flip-caption">クリックで裏面を見る</p></div>':'')+'<div class="eyebrow" style="color:'+color(c.cat)+'">'+c.en+'</div><div class="detail-hero"><div class="asset-art" style="--artbg:'+color(c.cat)+'33">'+icon(c.cat)+'</div><p class="detail-desc">'+c.desc+'</p></div><div class="detail-data"><div><label>開発コスト</label><div class="value">'+token(c.cat,c.cost)+(game&&developmentCost(game,game.turn,id)!==c.cost?'<small>現在の開発費：'+developmentCost(game,game.turn,id)+'</small>':'')+'</div></div><div><label>収入の出目</label><div class="dice-numbers">'+c.dice.map(n=>'<span class="die-small">'+n+'</span>').join('')+'</div></div><div><label>獲得する人材</label><div class="token-row">'+Object.entries(c.yields).map(([k,n])=>token(k,n)).join('')+'</div></div></div>'+(game?renderDevelopmentStatus(game,id,{busy:rolling||interactionBusy}):'')+'<div class="question-box"><small>THINK ABOUT IT</small><p>'+c.question+'</p></div><div class="callout">'+(c.verified?'このカードのコスト・出目・獲得人材は、添付された原版カードに基づきます。説明と問いは試作用に編集しています。':'このカードは仮設定です。名称・説明・コスト・出目・獲得人材は、カード一式の確認後に修正します。')+'</div>'+(c.art?'<details class="original"><summary>原版カードを見る</summary><img src="./assets/'+c.art+'" alt="'+c.name+'の原版カード"></details>':''),'<button class="outline" data-action="close">戻る</button>'+(owner>=0?'<span class="muted small">'+ROLES[owner].ja+' が所有</span>':game?'<button class="primary" data-action="build" data-id="'+id+'" '+(!ready?'disabled':'')+'>'+(ready?'開発する':'現在は開発できません')+'</button>':''));}
function showEvent(){modalKind='event';clearTimeout(aiTimer);modal.className='effect-dialog';modalContent.innerHTML=(tutorialSession?'<div class="tutorial-modal-hint">'+tutorialHint(tutorialSession)+'</div>':'')+renderNotice(game,{selectedId:eventChoiceId})+'<div class="effect-sound-control">'+soundButton()+'</div>';updateSoundLabels();if(!modal.open)modal.showModal();syncSelectColors(document);}
function showMission(i){if(!game||!canViewMission(game,i)){toast('他のプレイヤーのミッションは非公開です');return;}const p=game.players[i],c=effectById(p.mission);showModal(ROLES[i].name+' のミッション',c?'<div class="effect-card-reveal">'+renderFlippableCard({src:c.src,title:c.title,group:'mission',color:c.color})+'</div><p class="flip-caption">クリックで裏面を見る</p><p class="mission-status-text">'+colorText(missionProgress(game,i))+'</p><p class="modal-copy">課題：'+colorText(c.goal)+'<br>報酬：'+colorText(c.reward)+'</p>'+(c.ruleNote?'<p class="effect-rule-note">'+colorText(c.ruleNote)+'</p>':'')+'<p class="modal-copy">達成すると報酬を受け取り、同色の次のミッションを自動で引きます。</p>':'<p class="modal-copy">3枚のミッションをすべて達成しました。</p>','<button class="primary" data-action="close">シートへ戻る</button>');}
function showRules(){showModal('遊び方','<p class="modal-copy">人材を集めて量子アセットを開発します。最後はアセット数を比べ、プレイ中の選択を振り返りましょう。</p><ol class="rule-steps"><li><b>2個のサイコロを振る</b>合計がアセットの出目と一致すると、所有者は書かれた人材を獲得。他の人の手番でも収入があります。合計7なら、7カード（Good／Bad News）からランダムに1枚引きます。全体への効果が指定されていなければ、引いた人が対象です。</li><li><b>人材を使って、技術を開発する</b>コストと同じ色の人材を支払います。<span class="category-text category-wild">万能トークン</span>は不足分を補います。未開発のアセットは1枚につき1勢力だけが獲得できます。</li><li><b>交換や交渉をする</b>資材プールでは同じ色の人材2個を別の色1個と交換。勢力間では1対1の交換を提案できます。同じ端末の4人プレイなら相手が承認します。</li><li><b>手番を渡し、次の年へ</b>4勢力が行動すると、Historic Dayをランダムに1枚引き、全体への効果と選択を処理します。その後、ロールと同色の年次予算が1個入り、次の年に進みます。</li><li><b>結果から、対話をはじめる</b>11枚の獲得・全'+CARDS.length+'枚の開発・設定したラウンド数のいずれかで終了。アセット数、同数なら高コストの所有状況で順位がつきます。</li></ol><div class="callout">カードを選んで自分のシートへドラッグするか、「開発してシートへ」を押すと開発できます。開始時にロールをランダムに配布し、その色のMissionを1枚引きます。2041年から始まり、1ラウンドで1年進みます。達成すると報酬を受け取り、次の1枚を引きます。標準10ラウンド（8／12ラウンドも選択可）での終了、交渉の制限、同点処理などに試作上の解釈を含みます。CPUは定型の選択ルールでプレイします。</div><details class="operation-rules"><summary>抽選・期間・報酬の細かな扱い</summary><ul><li>任意の人材を選ぶ効果は青・赤・緑・黄の4種類が対象です。量子タレントは選べません。相手から受け取る場合も同じで、対象の人材が足りなければ持っている分だけ受け取ります。</li><li>7カードとHistoric Dayは、各10枚から重複なくランダムに引きます。山札が尽きたら捨て札を混ぜ直します。各ラウンドの全員の手番が終わったら、Historic Day → 年次予算の順に処理します。</li><li>未達成のミッションは本人だけが確認できます。1人プレイでは自分のロール、同じ端末の4人プレイでは現在の手番のプレイヤーが対象です。他のプレイヤーのシートやログには内容を表示しません。達成したミッションと報酬は全員に公開されます。</li><li>ミッションは同色の未達成カードから引きます。達成済みは戻さず、3枚達成で完了します。所有条件は現在の所有アセットでも達成できます。連続ラウンドの課題と交渉は、そのミッションを引いた後の行動を数えます。</li><li>「このラウンドを含む2ラウンド」は現在と次のラウンド。「このあとの3ラウンド」は次のラウンドから3回です。</li><li>共同研究では、つながったプレイヤーの人材を共有して支払えます。自分の人材から先に使い、残りを席順に使います。所持者の記録は保ち、期間終了時に残った人材を分割し直しません。NGOとの協力の報酬は、受け取る側が相手の所持トークンから2個を選びます。本人を対象とする喪失効果は、本人が所持する人材に適用します。</li><li>「任意のトークン」は万能も選べます。失う・渡す人材が足りなければ、持っている分だけ処理します。交換や譲渡、払い戻しでトークンを倍増させません。</li><li>同じ色のアセットをすべて所有すると、そのカテゴリを独占し、カテゴリのアセット収入が2倍になります。現在は各色6枚です。</li><li>倍増効果は掛け合わせます。「政府5か年計画」は期間中の新規獲得に適用し、交換・譲渡・払い戻しは除きます。永続報酬は達成した本人に残ります。</li><li>リープフロッグは連続する2ラウンドの開発で判定し、2枚目の実際の支払額をそのカテゴリの色で払い戻します。その手番の追加開発はできません。</li><li>手放したアセットは開発プールに戻ります。無料獲得の対象が残っていない場合、アセット追加なしで次のミッションへ進みます。</li><li>「左隣」は次の席として扱います（Eagle → Dragon → UD → Phoenix → Eagle）。複数人が選ぶHistoric DayはPhoenixから順に処理します。</li></ul></details>','<button class="primary" data-action="close">わかった</button>');}
function showAbout(){if(SINGLE_PLAYER_ONLY){showModal('Quantum Quest ブラウザ試遊版','<p class="modal-copy">あなた1人とCPU3勢力で遊ぶシングルプレイ版です。初めての方は、カードの種類や操作を順に学べるチュートリアルからお試しください。</p><p class="modal-copy">ロールはランダムに決まり、標準10ラウンドで進みます。最新の入稿カードと24枚のアセットを使用しています。ゲームの進行・対話メモはこのブラウザに保存されます。別の端末やブラウザには引き継がれません。</p><p class="modal-copy">開発中の試遊版です。ゲーム後は、競争や協力、技術の恩恵について振り返ってみてください。</p>','<button class="primary" data-action="close">閉じる</button>');return;}showModal('この試作について','<p class="modal-copy">Quantum Questのアプリ化に向けた、操作とゲーム進行を確かめるプロトタイプです。公式ルールスライドを基に、2026年10月16日受領の入稿版カード67枚（表面60枚・裏面7枚）と、追加のコスト1アセット4枚を反映しています。</p><table class="rules-table"><tr><th>反映済み</th><td>4ロールと初期条件／2ダイスによる全員への収入／4分野・'+CARDS.length+'枠／開発／<span class="category-text category-wild">万能トークン</span>／2対1交換／年次予算／2041年開始／11枚獲得または全アセット開発で終了</td></tr><tr><th>数値を確認</th><td>アセット全'+CARDS.length+'枚の名称・開発コスト・収入の出目・獲得人材。独占カード4枚の倍増対象も確認済み。</td></tr><tr><th>抽選の扱い</th><td>山札は重複なしで引き、7カード・Historic Dayは山札切れで再シャッフル。Missionは達成済みを再配布せず、3枚達成で完了。</td></tr><tr><th>試作用機能</th><td>ランダムなロール配布／標準10ラウンド制（8・12も選択可）／1人＋CPU3勢力／同じ端末で4人／交換の交渉は1対1に限定／途中保存／振り返りメモ／4人のシートの同時表示・自動更新／ドラッグ操作／添付原版'+REFERENCE_CARD_COUNT+'枚のカード資料室／独占カードの自動表示／7カード10枚・Historic Day10枚・Mission12枚の効果処理</td></tr><tr><th>オンライン</th><td>URLで卓に参加／人間・CPUの混在／自動同期／自分だけが読めるミッション／同じアカウントで再接続</td></tr><tr><th>追加予定</th><td>自由な交渉条件</td></tr></table><p class="modal-copy" style="margin-top:16px">シングルプレイの進行と対話メモはこのブラウザに保存します。マルチプレイの盤面はサーバーで共有し、同じアカウントで卓のURLを開くと再接続できます。対話メモはマルチプレイでも本人のブラウザ内に保存します。</p><div class="about-links"><a href="https://quantum-quest-card.github.io/index-ja.html" target="_blank" rel="noopener noreferrer">Quantum Quest 公式サイト ↗</a></div>','<button class="primary" data-action="close">閉じる</button>');}
function showExchange(){if(!canAct())return;const p={tokens:availableTokens(game,game.turn)};showModal('人材を交換する','<p class="modal-copy">同じ色の人材2個を、別の色の人材1個に交換します。<span class="category-text category-wild">万能トークン</span>は交換に使いません。</p><div class="form-grid"><div class="form-field"><label for="exchange-from">渡す人材 · 2個</label><select id="exchange-from" data-colored-select>'+CATEGORIES.map(c=>'<option data-color="'+c.id+'" style="color:'+textColors[c.id]+'" value="'+c.id+'">'+optionText(tokenName(c.id))+'（'+p.tokens[c.id]+'）</option>').join('')+'</select></div><span class="flow-arrow">→</span><div class="form-field"><label for="exchange-to">受け取る人材 · 1個</label><select id="exchange-to" data-colored-select>'+CATEGORIES.map((c,i)=>'<option data-color="'+c.id+'" style="color:'+textColors[c.id]+'" value="'+c.id+'" '+(i===1?'selected':'')+'>'+optionText(tokenName(c.id))+'</option>').join('')+'</select></div></div><p id="form-message" class="form-message"></p>','<button class="outline" data-action="close">戻る</button><button class="primary" data-action="do-exchange">交換する</button>');}
function showNegotiate(){if(!canAct())return;showModal('勢力と交渉する','<p class="modal-copy">この試作では、異なる色の人材を1個ずつ交換できます。'+(game.mode==='online'?'人間への提案は相手の画面に届き、相手が同意すると成立します。CPUは自分のロールと同色を受け取り、渡す人材を2個以上持つ場合に応じます。':game.mode==='solo'?'CPUは、手放す人材を2個以上持ち、受け取る色が自分のロールの色である場合に応じます。':'条件を選んだ後、相手に確認画面を見せてください。')+'</p><div class="form-field" style="margin-top:20px"><label for="trade-partner">交渉する相手</label><select id="trade-partner">'+ROLES.filter(r=>r.id!==game.turn).map(r=>'<option value="'+r.id+'">'+r.name+'</option>').join('')+'</select></div><div class="form-grid"><div class="form-field"><label for="trade-from">渡す人材 · 1個</label><select id="trade-from" data-colored-select>'+CATEGORIES.map(c=>'<option data-color="'+c.id+'" style="color:'+textColors[c.id]+'" value="'+c.id+'">'+optionText(tokenName(c.id))+'</option>').join('')+'</select></div><span class="flow-arrow">⇄</span><div class="form-field"><label for="trade-to">欲しい人材 · 1個</label><select id="trade-to" data-colored-select>'+CATEGORIES.map((c,i)=>'<option data-color="'+c.id+'" style="color:'+textColors[c.id]+'" value="'+c.id+'" '+(i===1?'selected':'')+'>'+optionText(tokenName(c.id))+'</option>').join('')+'</select></div></div><p id="form-message" class="form-message"></p>','<button class="outline" data-action="close">戻る</button><button class="primary" data-action="offer-trade">提案する</button>');}
let pendingTrade=null;
function offerTrade(){if(!canAct())return;const other=+document.querySelector('#trade-partner').value,from=document.querySelector('#trade-from').value,to=document.querySelector('#trade-to').value;const msg=document.querySelector('#form-message');if(from===to){msg.textContent='違う色の人材を選んでください。';return;}if(availableTokens(game,game.turn)[from]<1||availableTokens(game,other)[to]<1){msg.textContent='どちらかの勢力が、指定された人材を持っていません。';return;}if(game.mode==='solo'){if(availableTokens(game,other)[to]<2||ROLES[other].cat!==from){msg.textContent='CPUは今回の条件を見送りました。条件を変えて提案できます。';return;}trade(game,other,from,to);modal.close();save();render();toast('交換が成立しました');return;}pendingTrade={other,from,to};showModal(ROLES[other].name+' への提案','<p class="modal-copy">'+ROLES[game.turn].name+' からの提案です。この端末を相手に見せてください。</p><div class="question-box"><small>TRADE OFFER</small><p>受け取る：'+colorText(tokenName(from))+' 1個<br>渡す：'+colorText(tokenName(to))+' 1個</p></div>','<button class="outline" data-action="decline-trade">断る</button><button class="primary" data-action="accept-trade">相手として承認する</button>');}
const prompts=['あなたの選択を最も変えた出来事は何でしたか？','競争と協力の間で、どのような迷いがありましたか？','このゲームで描かれた未来に、登場していない人や価値はありますか？'];
function sameScore(a,b){return a.assets.length===b.assets.length&&JSON.stringify(a.assets.map(id=>cardById(id).cost).sort((x,y)=>y-x))===JSON.stringify(b.assets.map(id=>cardById(id).cost).sort((x,y)=>y-x));}
function renderReflection(){const ranked=ranking(game);let lastRank=1;main.innerHTML='<div class="reflection"><div class="reflection-header"><div><div class="eyebrow">BEYOND THE GAME</div><h1>あなたがつくった未来を、<br>話してみよう。</h1><p class="reflection-intro">'+e(game.endedReason||'ゲーム終了')+'<br>結果を手がかりに、選んだ道と、選ばなかった道を考えてみましょう。</p></div><button class="outline small" data-action="review-log">プレイの記録を見る</button></div><div class="result-strip">'+ranked.map((p,i)=>{if(i===0||!sameScore(p,ranked[i-1]))lastRank=i+1;return '<div class="result" style="--cat:'+color(ROLES[p.role].cat)+'"><div class="result-rank">'+String(lastRank).padStart(2,'0')+' / '+(lastRank<=2?'入賞':'RESULT')+'</div><div class="result-score">'+p.assets.length+'<small>ASSETS</small></div><div class="result-name">'+ROLES[p.role].name+(game.mode==='solo'&&p.role===game.human?' <span class="solo-tag">YOU</span>':'')+'</div><div class="owned-mini">'+p.assets.map(id=>'<i style="--cat:'+color(cardById(id).cat)+'"></i>').join('')+'</div></div>';}).join('')+'</div><p class="tie-note">アセット数を比較し、同数なら高コストのカードから比較。同じ構成は同順位です。社会的に望ましい選択かどうかを採点するものではありません。</p><div class="reflection-grid"><section><h2>この世界に起きたこと</h2>'+(game.events.length?game.events.filter((_,i)=>i<16).map(ev=>'<div class="event-list-item"><time>'+ev.year+'年 · '+e(ev.label)+'</time><b>'+colorText(ev.title)+'</b><p>'+colorText(ev.text)+'</p></div>').join(''):'<p class="modal-copy">まだイベントは発生していません。最初の条件や、選ぼうとした技術から振り返ってみましょう。</p>')+'<p class="microcopy">原版カードと、今回確認した抽選ルールに基づく記録です。</p></section><section><h2>対話のためのメモ</h2>'+prompts.map((q,i)=>'<div class="reflection-prompt"><label for="note-'+i+'"><small>QUESTION 0'+(i+1)+'</small>'+q+'</label><textarea id="note-'+i+'" data-note="'+i+'" placeholder="気づいたこと、まだ答えが出ないこと。自由に書いてみましょう。">'+e(game.notes[i]||'')+'</textarea></div>').join('')+'<p class="microcopy">メモはこのブラウザに保存されます。ほかの人には送信されません。</p></section></div><div class="reflection-actions"><button class="outline" data-action="home">ホームへ戻る</button><button class="primary" data-action="export">記録とメモを保存 ↓</button></div></div>';}
function exportRecord(){const lines=['Quantum Quest / 試遊版 0.10.0',new Date().toLocaleString('ja-JP'),game.endedReason,'','注意：公式ルール v2.12＋追加のコスト1アセット4枚。アセット'+CARDS.length+'枚の数値は原版反映済み。7カード・Historic Day・Missionの効果を実装。','','結果',...ranking(game).map(p=>ROLES[p.role].name+'：'+p.assets.length+'アセット（'+p.assets.map(id=>cardById(id).name).join('、')+'）'),'','対話のメモ',...prompts.flatMap((q,i)=>[q,game.notes[i]||'（未記入）','']),'プレイの記録',...filteredLog(game).slice().reverse().map(l=>l.year+'年 '+l.text)];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Quantum_Quest_振り返り.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('記録とメモを書き出しました');}
function scheduleCpu(){clearTimeout(aiTimer);if(onlineActive)return;if(tutorialSession||soundDialog.open||eventSuspended)return;if(screen!=='game'||!game||game.phase==='finished'||interactionBusy||rolling)return;if(game.notice){if(game.notice.type==='choice'&&game.mode==='solo'&&game.notice.actor!==game.human){aiTimer=setTimeout(()=>{if(tutorialSession||eventSuspended||soundDialog.open||screen!=='game'||!game.notice||game.notice.type!=='choice'||game.notice.actor===game.human)return;autoResolveChoice(game);modal.close();save();render();},fast?180:850);}return;}if(!isCpu()||modal.open)return;aiTimer=setTimeout(()=>{if(tutorialSession||eventSuspended||soundDialog.open||screen!=='game'||modal.open||!isCpu()||game.notice||interactionBusy||rolling)return;if(game.phase==='roll')roll(game);else if(!aiAction(game))endTurn(game);save();render();},fast?180:1100);}
function startGame(){selectedId=null;matSeat=null;matPinned=false;lastRenderedTurn=null;logFilter='all';game=createGame({mode,maxRounds,seed:crypto.getRandomValues(new Uint32Array(1))[0]});sounds.stop();gameSounds.reset(game);screen='game';tab='market';filter='all';onlyAvailable=true;modal.close();save();render();showRoleDeal();window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',ev=>{const btn=ev.target.closest('[data-action]');if(!btn||btn.disabled)return;if(Date.now()<suppressClickUntil)return;const a=btn.dataset.action,id=btn.dataset.id;
 if(handleOnlineClick(a,id))return;
 if(tutorialSession&&!tutorialAllows(tutorialSession,a,id,document.querySelector('#effect-choice')?.value)){toast('練習ガイドに書かれた操作・選択を試してください。');return;}
 switch(a){case 'tutorial-start':startTutorial();break;case 'tutorial-restart':startTutorial();break;case 'tutorial-exit':exitTutorial();break;case 'tutorial-next':if(tutorialSession&&nextTutorial(tutorialSession)){selectedId=null;modal.close();render();window.scrollTo({top:0,behavior:'instant'});}break;case 'tutorial-prev':if(tutorialSession&&previousTutorial(tutorialSession)){selectedId=null;render();window.scrollTo({top:0,behavior:'instant'});}break;case 'tutorial-guide':if(tutorialSession){if(game.notice)pauseEvent();showModal('カード・用語のガイド',renderTutorialGuide(),'<button class="primary" data-action="close">練習に戻る</button>','catalog-view');}break;case 'tutorial-scene':if(tutorialSession&&performTutorialScene(tutorialSession)){render();}break;case 'suspend-event':pauseEvent();break;case 'resume-event':eventSuspended=false;render();break;case 'token-guide':showModal('人材トークン',renderTokenGuide(),'<button class="primary" data-action="close">テーブルへ戻る</button>');break;case 'sound-settings':showSoundSettings();break;case 'sound-close':closeSoundSettings();break;case 'sound-sample':previewSound(id);break;case 'flip-card':{sounds.play('flip');btn.classList.remove('reveal-card');const back=btn.classList.toggle('show-back');btn.setAttribute('aria-pressed',String(back));btn.setAttribute('aria-label',btn.querySelector('.turnable-front').alt+'。'+(back?'表面を見る':'裏面を見る'));break;}case 'log-filter':logFilter=id;document.querySelector('.activity-scroll')?.scrollTo(0,0);render();break;case 'log-latest':document.querySelector('.activity-scroll')?.scrollTo({top:0,behavior:reducedMotion()?'instant':'smooth'});break;case 'mission-view':showMission(+id);break;case 'resolve-event':{if(game.notice?.type==='choice'&&(game.mode==='table'||game.notice.actor===game.human)){const choice=document.querySelector('#effect-choice')?.value;if(resolveChoice(game,choice)){modal.close();save();render();}}break;}case 'event-reference':showEventReference(id);break;case 'select-card':selectedId=id;render();if(tutorialSession)document.querySelector('.table-inspector')?.scrollIntoView({block:'center',behavior:'smooth'});break;case 'view-seat':case 'inspect-seat':matSeat=+id;matPinned=true;render();if(a==='inspect-seat')document.querySelector('.mat-section')?.scrollIntoView({block:'start',behavior:reducedMotion()?'instant':'smooth'});break;case 'role-card':showRole(+id);break;case 'catalog':catalogRole='all';showCatalog(id);break;case 'catalog-filter':showCatalog(id);break;case 'catalog-role':catalogRole=id;showCatalog(catalogFilter);break;case 'catalog-card':showCatalogCard(id);break;case 'catalog-next':stepCatalog(+id);break;case 'historic-year':showHistoricYear(id);break;case 'layout-guide':showLayoutGuide();break;case 'sheet-guide':showSheetGuide();break;case 'home':if(!rolling&&!interactionBusy)home();break;case 'rules':showRules();break;case 'about':showAbout();break;case 'close':case 'ack':closeModal();break;case 'mode':mode=id;renderHome();break;case 'new':if(game){showModal('新しい体験をはじめる','<p class="modal-copy">このブラウザの前回のゲームとメモを、新しいゲームで置き換えます。</p>','<button class="outline" data-action="close">戻る</button><button class="primary" data-action="confirm-new">はじめる</button>');}else startGame();break;case 'confirm-new':startGame();break;case 'resume':screen=game.phase==='finished'?'reflection':'game';render();break;case 'tab':tab=id;render();break;case 'filter':filter=id;render();break;case 'detail':showDetail(id);break;case 'roll':rollDice();break;case 'end':if(canAct()&&!rolling&&!interactionBusy){matPinned=false;endTurn(game);save();render();}break;case 'build':developCard(id);break;case 'exchange':showExchange();break;case 'do-exchange':if(canAct()){const from=document.querySelector('#exchange-from').value,to=document.querySelector('#exchange-to').value;if(tutorialSession&&(from!=='yellow'||to!=='green')){document.querySelector('#form-message').textContent='この練習では、黄色2個を緑1個に交換してください。';break;}if(exchange(game,from,to)){modal.close();save();render();toast('人材を交換しました');}else document.querySelector('#form-message').textContent=from===to?'違う色を選んでください。':'渡す色の人材が2個必要です。';}break;case 'negotiate':showNegotiate();break;case 'offer-trade':offerTrade();break;case 'accept-trade':if(canAct()&&pendingTrade){if(trade(game,pendingTrade.other,pendingTrade.from,pendingTrade.to)){pendingTrade=null;modal.close();save();render();toast('交換が成立しました');}}break;case 'decline-trade':pendingTrade=null;closeModal();toast('今回の交換を見送りました');break;case 'finish':showModal('ここまでのプレイを振り返る','<p class="modal-copy">現在の状況でゲームを終了し、結果と対話のメモを開きます。</p>','<button class="outline" data-action="close">プレイを続ける</button><button class="primary" data-action="confirm-finish">振り返りへ</button>');break;case 'confirm-finish':finish(game);modal.close();save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'review-log':showModal('プレイの記録','<p class="modal-copy">新しい出来事から表示しています。</p><ol class="activity-list full-log">'+renderLogEntries(game)+'</ol>','<button class="primary" data-action="close">閉じる</button>');break;case 'export':exportRecord();break;case 'export-legacy':exportLegacyRecord();break;case 'domination-card':showDomination(id);break;}
});
document.addEventListener('change',ev=>{if(onlineActive&&ev.target.dataset?.onlineSeat!==undefined){onlineAction('configure',{seat:+ev.target.dataset.onlineSeat,kind:ev.target.value});return;}if(onlineActive&&ev.target.id==='lobby-rounds'){onlineAction('configure',{maxRounds:+ev.target.value});return;}if(ev.target.id==='sound-enabled'){sounds.setEnabled(ev.target.checked);syncSoundSettings();if(ev.target.checked)previewSound('flip');return;}if(ev.target.id==='sound-volume'){previewSound('income');return;}syncSelectColors(document);if(ev.target.id==='effect-choice'){eventChoiceId=ev.target.value;document.querySelector('#choice-preview').innerHTML=choicePreview(game,ev.target.value);}if(ev.target.id==='round-count')maxRounds=+ev.target.value;if(ev.target.id==='only-available'){onlyAvailable=ev.target.checked;render();}if(ev.target.id==='fast-cpu'){fast=ev.target.checked;scheduleCpu();}});
document.addEventListener('input',ev=>{if(ev.target.id==='tutorial-note'&&tutorialSession){tutorialSession.reflection=ev.target.value;return;}if(ev.target.id==='sound-volume'){sounds.setVolume(Number(ev.target.value)/100);syncSoundSettings();return;}if(ev.target.matches('[data-note]')){game.notes[+ev.target.dataset.note]=ev.target.value;save();}});
function reducedMotion(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
function rollDice(){if(onlineActive){if(!myTurn()||onlineBusy||game.phase!=='roll'||game.notice||onlineRoom.pendingTrade)return;gameSounds.beginRoll(game);sounds.play('dice');onlineAction('roll');return;}
 if(screen!=='game'||isCpu()||game.phase!=='roll'||game.notice||rolling||interactionBusy)return;
 const rollingGame=game;gameSounds.beginRoll(game);sounds.play('dice');rolling=true;clearTimeout(aiTimer);renderBoard();
 setTimeout(()=>{if(game!==rollingGame)return;rolling=false;if(screen!=='game'||game.phase!=='roll')return;const before=game.players.map(p=>({...p.tokens}));roll(game);save();render();if(!game.notice&&matSeat!==null){const changed=Object.keys(before[matSeat]).some(k=>before[matSeat][k]!==game.players[matSeat].tokens[k]);if(changed)document.querySelectorAll('.mat-token-space .game-coin').forEach(el=>el.classList.add('gain-pulse'));}},reducedMotion()?30:650);
}
function developCard(id,dragRect){if(onlineActive){if(canAct()){selectedId=id;matSeat=game.human;onlineAction('build',{cardId:id});}return;}
 if(!canAct()||rolling||interactionBusy)return;
 if(tutorialSession&&!tutorialAllows(tutorialSession,'build',id)){toast('ガイドで紹介しているカードを選んでください。');return;}
 const source=document.querySelector('.physical-card[data-card-id="'+id+'"]');
 const origin=dragRect||source?.getBoundingClientRect();const sourceFace=source?.querySelector('.card-face')?.outerHTML;const c=cardById(id);
 if(!c||!build(game,id)){toast(developmentView(game,id).reason||'このカードは今は開発できません。');return;}
 matSeat=game.turn;matPinned=false;selectedId=id;interactionBusy=true;modal.close();save();render();
 const target=document.querySelector('[data-owned-card="'+id+'"]');
 const developedGame=game;
 const stop=()=>{if(game!==developedGame)return;interactionBusy=false;render();document.querySelector('[data-owned-card="'+id+'"]')?.classList.add('just-placed');toast(c.name+' をシートに置きました');};
 if(!target||!origin||reducedMotion()){stop();return;}
 const dest=target.getBoundingClientRect();
 if(dest.top>innerHeight||dest.bottom<0){target.scrollIntoView({block:'center',behavior:'smooth'});stop();return;}
 const flying=document.createElement('div');flying.className='flying-card';flying.setAttribute('aria-hidden','true');
 Object.assign(flying.style,{left:origin.left+'px',top:origin.top+'px',width:origin.width+'px',height:origin.height+'px','--cat':color(c.cat)});
 flying.innerHTML=c.art?'<img src="./assets/'+c.art+'" alt="">':sourceFace||'';document.body.appendChild(flying);
 const anim=flying.animate([{transform:'translate(0,0) rotate(-3deg)',opacity:1},{transform:'translate('+((dest.left-origin.left)*.48)+'px,'+((dest.top-origin.top)*.48-30)+'px) rotate(4deg)',opacity:1,offset:.48},{transform:'translate('+(dest.left-origin.left)+'px,'+(dest.top-origin.top)+'px) scale('+(dest.width/origin.width)+','+(dest.height/origin.height)+') rotate(0)',opacity:1}],{duration:480,easing:'cubic-bezier(.22,.68,.3,1)',fill:'forwards'});
 anim.finished.catch(()=>{}).finally(()=>{flying.remove();stop();});
}
function exportLegacyRecord(){if(!legacyGame)return;const lines=['Quantum Quest / 旧版のプレイ記録','旧版のカード数値・名称には仮設定が含まれます。','','対話のメモ',...legacyGame.notes.map(String),'','プレイの記録',...legacyGame.log.slice().reverse().map(l=>l.year+'年 '+l.text)];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Quantum_Quest_旧版の記録.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function showDomination(cat){try{await loadCatalog();catalogFilter='domination';catalogRole='all';showCatalogCard('domination-'+cat);}catch{toast('独占カードを読み込めませんでした。');}}
function showRole(id){const r=ROLES[id];if(!r)return;showModal(r.name,'<div class="role-card-preview">'+renderFlippableCard({src:'./assets/'+['eagle','dragon','unity','phoenix'][id]+'.png',title:r.name,group:'role',portrait:true})+'</div><p class="flip-caption">クリックで表・裏を確認</p><p class="modal-copy">'+colorText(r.desc)+'</p>','<button class="primary" data-action="close">戻る</button>');}
function showRoleDeal(){sounds.play('flip');const personal=game.mode==='solo'||game.mode==='online';const ids=personal?[game.human]:game.playerOrder;showModal(personal?'あなたのロールが決まりました。':'4人のロールが決まりました。','<p class="modal-copy">2041年、ここから始まる量子の未来。<br>復活の不死鳥から順にプレイします。</p><div class="role-deal-grid '+(personal?'solo-deal':'')+'">'+ids.map(i=>{const r=ROLES[i],m=effectById(game.players[i].mission);return '<div class="role-dealt" style="--cat:'+color(r.cat)+'"><span class="dealt-player">'+(personal?'YOUR ROLE':'PLAYER '+playerNumber(game,i))+'</span>'+renderFlippableCard({src:'./assets/'+['eagle','dragon','unity','phoenix'][i]+'.png',title:r.name,group:'role',portrait:true,reveal:true})+'<strong>'+e(r.name)+'</strong><small>'+e(r.ja)+'</small>'+(personal&&m?'<div class="dealt-mission"><span>最初のミッション</span>'+renderFlippableCard({src:m.src,title:m.title,group:'mission',color:r.cat,reveal:true})+'<b>'+colorText(m.title)+'</b></div>':'')+'</div>';}).join('')+'</div>','<button class="primary" data-action="close">2041年をはじめる →</button>','role-deal');}

async function loadCatalog(){if(catalog)return catalog;const r=await fetch('./assets/card-catalog.json');if(!r.ok)throw Error('catalog');catalog=await r.json();return catalog;}
function catalogItems(){return (catalog||[]).filter(c=>(catalogFilter==='all'||c.group===catalogFilter)&&(catalogFilter!=='mission'||catalogRole==='all'||c.color===catalogRole));}
const groupName=k=>({historic:'Historic Day',news:'Good / Bad News',mission:'Mission',asset:'アセット',role:'ロール',domination:'独占'}[k]||'すべて');
async function showCatalog(which='all'){
 clearTimeout(aiTimer);
 try{await loadCatalog();}catch{showModal('カード資料室','<p class="modal-copy">画像一覧を読み込めませんでした。ページを再読み込みしてお試しください。</p>');return;}
 catalogFilter=which;const items=catalogItems();
 showModal('カード資料室','<p class="catalog-intro">添付された原版'+REFERENCE_CARD_COUNT+'枚です。クリックで拡大し、文章も確認できます。<br>この資料室は閲覧用です。カードを開いても、ゲームの資源や進行は変わりません。</p><div class="catalog-filters">'+['all','asset','role','domination','historic','news','mission'].map(k=>'<button class="'+(which===k?'active':'')+'" data-action="catalog-filter" data-id="'+k+'">'+groupName(k)+'</button>').join('')+'</div>'+(which==='mission'?'<div class="catalog-filters"><button data-action="catalog-role" data-id="all" class="'+(catalogRole==='all'?'active':'')+'">全ロール</button>'+ROLES.map(r=>'<button data-action="catalog-role" data-id="'+r.cat+'" class="'+(catalogRole===r.cat?'active':'')+'">'+r.name+'</button>').join('')+'</div>':'')+'<div class="catalog-grid">'+items.map(c=>'<button class="catalog-item catalog-'+(c.orientation||'landscape')+'" data-action="catalog-card" data-id="'+c.id+'"><img src="'+c.src+'" alt="'+e(c.title)+'" loading="lazy"><b>'+colorText(c.title)+'</b><small>'+groupName(c.group)+(c.year?' / '+c.year:c.color?' / '+c.color.toUpperCase():'')+'</small></button>').join('')+'</div><p class="catalog-note">7カードとHistoric Dayはプレイ中に自動抽選します。Missionも達成を自動判定します。この資料室からは効果を適用しません。</p>','<button class="primary" data-action="close">テーブルへ戻る</button>','catalog-view');
}
function showCatalogCard(id){const c=catalog?.find(c=>c.id===id);if(!c)return;const items=catalogItems();catalogIndex=items.findIndex(x=>x.id===id);showModal(c.title,'<div class="catalog-flip '+(c.orientation||'landscape')+'">'+renderFlippableCard({src:c.src,title:c.title,group:c.group,color:c.color,portrait:c.orientation==='portrait'})+'</div><p class="flip-caption">クリックで表・裏を確認</p><div class="catalog-card-text"><details><summary>カードの文章をテキストで読む</summary><p>'+colorText(c.text)+'</p></details></div>'+(c.note?'<p class="catalog-note">'+colorText(c.note)+'</p>':'')+'<p class="catalog-note">原版の閲覧です。この画面からゲームへの効果は適用しません。</p><div class="catalog-paging"><button class="outline" data-action="catalog-next" data-id="-1" '+(catalogIndex<=0?'disabled':'')+'>← 前のカード</button><span>'+ (catalogIndex+1)+' / '+items.length+'</span><button class="outline" data-action="catalog-next" data-id="1" '+(catalogIndex>=items.length-1?'disabled':'')+'>次のカード →</button></div>','<button class="outline" data-action="catalog-filter" data-id="'+catalogFilter+'">一覧へ</button><button class="primary" data-action="close">閉じる</button>');}
function stepCatalog(direction){const items=catalogItems();const next=items[catalogIndex+direction];if(next)showCatalogCard(next.id);}
async function showEventReference(id){try{await loadCatalog();catalogFilter=effectById(id).group;catalogRole='all';showCatalogCard(effectById(id).catalogId);}catch{toast('原版カードを読み込めませんでした。');}}
async function showHistoricYear(year){try{await loadCatalog();catalogFilter='historic';catalogRole='all';const c=catalog.find(c=>c.year===year);if(c)showCatalogCard(c.id);}catch{toast('原版カードを読み込めませんでした。');}}
function showLayoutGuide(){showModal('共通の場の配置','<p class="modal-copy">manual_p3の配置をもとに、4色の開発プールが共通の山札・サイコロ・人材プールを囲みます。小さい画面では、操作しやすいように縦に並びます。</p><div class="reference-window"><img class="reference-image" src="./assets/manual_p3.png" alt="添付されたゲーム配置図"></div>','<button class="primary" data-action="close">テーブルへ戻る</button>');}
function showSheetGuide(){showModal('プレイヤーシートの使い方','<ol class="sheet-instructions"><li><b>左上：ロール。</b>カードを押すと役割の説明を拡大できます。</li><li><b>上段と左下：所有アセット。</b>開発できるカードをこのシートにドラッグすると、人材を支払ってカードを置けます。</li><li><b>右下：所有する人材。</b>トークンに重なる数字が所持数です。</li></ol><p class="modal-copy">カードをクリックし「開発してシートへ」を押しても同じ操作ができます。画面上部には4人全員のシートが並び、人材やアセットの変化が自動で反映されます。自分の手番には、上部の自分のシートにもドラッグして開発できます。小さなカードを押すと拡大できます。「シートを詳しく」で大きなシートを開けます。他のプレイヤーの未達成ミッションは非公開です。</p><div class="reference-window"><div class="player-mat"><div class="mat-original"><img src="./assets/sheet_asset.png" alt="添付されたプレイヤーシート"></div></div></div>','<button class="primary" data-action="close">わかった</button>');}
function cancelDrag(){if(!dragState)return;dragState.ghost?.remove();dragState.button?.classList.remove('source-being-dragged');document.querySelectorAll('.drag-target,.drop-invalid').forEach(el=>el.classList.remove('drag-target','drop-invalid'));document.body.classList.remove('dragging-card');if(dragState.raf)cancelAnimationFrame(dragState.raf);dragState=null;interactionBusy=false;scheduleCpu();}
function updateDropTarget(x,y){document.querySelectorAll('.drag-target').forEach(el=>el.classList.remove('drag-target'));const mat=document.elementFromPoint(x,y)?.closest('.player-mat[data-owner]');if(mat&&+mat.dataset.owner===game.turn){mat.classList.add('drag-target');return mat;}return null;}
function dragAutoScroll(){if(!dragState?.active)return;const y=dragState.y;const speed=y<65?-12:y>innerHeight-70?12:0;if(speed){window.scrollBy(0,speed);updateDropTarget(dragState.x,dragState.y);}dragState.raf=requestAnimationFrame(dragAutoScroll);}
document.addEventListener('pointerdown',ev=>{
 const button=ev.target.closest('[data-grab="true"]');if(!button||ev.button!==0||!canAct()||rolling||interactionBusy||modal.open)return;
 const id=button.dataset.id;if(tutorialSession&&!tutorialAllows(tutorialSession,'build',id))return;if(!canBuild(game,game.turn,id))return;
 dragState={id,button,pointer:ev.pointerId,startX:ev.clientX,startY:ev.clientY,x:ev.clientX,y:ev.clientY,active:false,origin:button.getBoundingClientRect()};button.setPointerCapture(ev.pointerId);
});
document.addEventListener('pointermove',ev=>{
 if(!dragState||dragState.pointer!==ev.pointerId)return;dragState.x=ev.clientX;dragState.y=ev.clientY;
 if(!dragState.active&&Math.hypot(ev.clientX-dragState.startX,ev.clientY-dragState.startY)>9){
  dragState.active=true;interactionBusy=true;clearTimeout(aiTimer);const ghost=dragState.button.cloneNode(true);ghost.className='physical-card floating-card';ghost.removeAttribute('data-action');ghost.setAttribute('aria-hidden','true');ghost.removeAttribute('aria-label');ghost.tabIndex=-1;ghost.style.width='88px';ghost.style.height='123px';document.body.appendChild(ghost);dragState.ghost=ghost;dragState.button.classList.add('source-being-dragged');document.body.classList.add('dragging-card');dragState.raf=requestAnimationFrame(dragAutoScroll);
 }
 if(dragState.active){ev.preventDefault();dragState.ghost.style.left=(ev.clientX-44)+'px';dragState.ghost.style.top=(ev.clientY-65)+'px';dragState.ghost.style.transform='rotate(-7deg)';updateDropTarget(ev.clientX,ev.clientY);}
},{passive:false});
document.addEventListener('pointerup',ev=>{
 if(!dragState||dragState.pointer!==ev.pointerId)return;const d=dragState;
 if(!d.active){cancelDrag();return;}
 ev.preventDefault();suppressClickUntil=Date.now()+400;const dest=updateDropTarget(ev.clientX,ev.clientY);const origin=d.ghost.getBoundingClientRect();cancelDrag();
 if(dest)developCard(d.id,origin);else{toast('自分のプレイヤーシートに置いてください。クリックでも開発できます。');}
});
document.addEventListener('pointercancel',cancelDrag);
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&dragState){cancelDrag();toast('カードを元の場所に戻しました。');}});
window.addEventListener('blur',cancelDrag);
render();

function pauseEvent(){if(!game?.notice)return;eventChoiceId=document.querySelector('#effect-choice')?.value??eventChoiceId;eventSuspended=true;clearTimeout(aiTimer);modal.close();render();}

function resetInteraction(){clearTimeout(aiTimer);cancelDrag();rolling=false;interactionBusy=false;selectedId=null;matSeat=null;matPinned=false;lastRenderedTurn=null;eventNoticeRef=null;eventSuspended=false;eventChoiceId=null;pendingTrade=null;modal.close();sounds.stop();gameSounds.reset(game);}
function startTutorial(){if(!tutorialSession)regularGame=game;tutorialSession=createTutorial();game=tutorialSession.game;resetInteraction();screen='game';render();window.scrollTo({top:0,behavior:'instant'});}
function exitTutorial(){if(!tutorialSession)return;game=regularGame;regularGame=null;tutorialSession=null;resetInteraction();screen='home';render();window.scrollTo({top:0,behavior:'instant'});}

function onlineRecent(){try{return (JSON.parse(localStorage.getItem('quantum-quest-rooms-v1'))||[]).filter(r=>/^[a-f0-9]{48}$/.test(r.id)).slice(0,6);}catch{return [];}}
function onlineName(){try{return localStorage.getItem('quantum-quest-online-name')||'';}catch{return '';}}
function rememberOnline(room){try{const recent=[{id:room.id,name:room.seats[0].name+' の卓'},...onlineRecent().filter(r=>r.id!==room.id)].slice(0,6);localStorage.setItem('quantum-quest-rooms-v1',JSON.stringify(recent));}catch{}}
function onlineNotesKey(){return 'quantum-quest-room-notes-'+onlineRoom.id+'-'+onlineRoom.role;}
function onlineConnectionError(error,loud){onlineError=error;if(loud)toast(error.message);if(onlineActive&&!onlineRoom)renderOnlineWaiting();}
function onlineConnectionStatus(status){const changed=onlineStatus!==status;onlineStatus=status;if(changed&&onlineActive&&onlineRoom)render();}
function renderOnlineWaiting(){
 document.querySelector('#header-status').textContent='MULTIPLAYER LOBBY';
 if(onlineRoom){main.innerHTML=renderLobby(onlineRoom,{name:onlineName(),invite:roomInviteURL(onlineRoom.id,window.location?.origin||''),busy:onlineBusy});return;}
 main.innerHTML='<div class="online-connection"><div class="eyebrow">MULTIPLAYER</div><h1>'+e(onlineError?'卓への接続を確認してください':'卓に接続しています…')+'</h1><p>'+e(onlineError?.message||'同じ卓の参加状況を読み込んでいます。')+'</p>'+(onlineError?.signIn?'<a class="primary" href="'+e(onlineError.signIn)+'" target="_top">ログインして参加する</a>':'<button class="primary" data-action="online-retry">再接続</button>')+'<button class="outline" data-action="online-home">ホームへ戻る</button></div>';
}
function beginOnline(){
 if(tutorialSession)exitTutorial();if(!onlineActive)localGameBeforeOnline=game;
 onlineActive=true;onlineRoom=null;onlineBusy=false;onlineError=null;onlineStatus='connecting';game=null;screen='online';
 clearTimeout(aiTimer);rolling=false;interactionBusy=false;eventSuspended=false;eventNoticeRef=null;selectedId=null;matSeat=null;matPinned=false;
 if(modal.open)modal.close();sounds.stop();gameSounds.reset(null);render();
}
function acceptOnlineRoom(room){
 if(!onlineActive)return;
 const prior=onlineRoom;if(prior?.id===room.id&&prior.revision===room.revision){onlineError=null;return;}
 const entering=!!room.game&&!prior?.game;onlineRoom=room;onlineError=null;rememberOnline(room);
 if(window.history&&window.location)window.history.replaceState(null,'','/?room='+room.id);
 if(room.game){
  let notes=['','',''];if(!entering&&game?.mode==='online')notes=game.notes;else try{const saved=JSON.parse(localStorage.getItem(onlineNotesKey()));if(Array.isArray(saved)&&saved.length===3&&saved.every(x=>typeof x==='string'))notes=saved;}catch{}
  const next=room.game;next.notes=notes;
  if(game?.mode==='online'&&!entering){const oldNotice=game.notice;if(JSON.stringify(oldNotice)===JSON.stringify(next.notice))next.notice=oldNotice;Object.assign(game,next);}else game=next;
  if(modalKind==='event'&&!game.notice&&modal.open)modal.close();
  if(entering){screen='game';matSeat=game.human;gameSounds.reset(game);}
  render();if(entering&&game.phase!=='finished'&&!game.notice)showRoleDeal();
 }else{game=null;screen='online';renderOnlineWaiting();}
}
function leaveOnlineView(){
 onlineClient.disconnect();save();onlineActive=false;onlineRoom=null;onlineBusy=false;onlineError=null;game=localGameBeforeOnline;localGameBeforeOnline=null;
 screen='home';mode='online';rolling=false;interactionBusy=false;eventSuspended=false;eventNoticeRef=null;matSeat=null;matPinned=false;
 if(modal.open)modal.close();sounds.stop();gameSounds.reset(game);if(window.history)window.history.replaceState(null,'','/');render();
}
async function openOnline(id){if(!/^[a-f0-9]{48}$/.test(id)){toast('招待URLをご確認ください。');return;}beginOnline();try{await onlineClient.connect(id);}catch{}}
async function onlineAction(type,values={}){
 if(!onlineActive||!onlineRoom||onlineBusy||onlineStatus!=='connected')return;
 onlineBusy=true;const id=onlineRoom.id;if(modal.open&&type!=='configure')modal.close();
 if(screen==='game')renderBoard();else if(!game)renderOnlineWaiting();
 try{await onlineClient.command(type,values);if(type==='build'&&onlineActive&&onlineRoom?.id===id){document.querySelector('[data-owned-card="'+values.cardId+'"]')?.classList.add('just-placed');}}
 catch{}finally{if(onlineActive&&onlineRoom?.id===id){onlineBusy=false;render();}}
}
async function copyOnlineInvite(){
 if(!onlineRoom)return;const url=roomInviteURL(onlineRoom.id,window.location?.origin||'');
 try{await navigator.clipboard.writeText(url);toast('参加用URLをコピーしました');}
 catch{showModal('参加用URL','<p class="modal-copy">このURLを参加者に共有してください。</p><input style="width:100%" readonly value="'+e(url)+'" aria-label="参加用URL">','<button class="primary" data-action="close">閉じる</button>');}
}
function handleOnlineClick(action,id){
 if(SINGLE_PLAYER_ONLY&&(action.startsWith('online-')||action==='mode'&&id!=='solo')){toast('この試遊版はシングルプレイ用です。');return true;}
 if(action==='online-create'){
  const name=document.querySelector('#online-name')?.value.trim();if(!name){toast('表示名を入力してください。');return true;}
  const seats=[1,2,3].map(i=>document.querySelector('#online-seat-'+i).value),rounds=+document.querySelector('#online-rounds').value;
  try{localStorage.setItem('quantum-quest-online-name',name);}catch{}
  beginOnline();onlineClient.create({name,seats,maxRounds:rounds}).catch(error=>{onlineConnectionStatus('disconnected');onlineConnectionError(error,true);});return true;
 }
 if(action==='online-open'){openOnline(id);return true;}
 if(!onlineActive)return false;
 switch(action){
  case 'online-home':case 'home':leaveOnlineView();return true;
  case 'online-copy':copyOnlineInvite();return true;
  case 'online-retry':onlineClient.retry();return true;
  case 'online-join':{
   const name=document.querySelector('#online-join-name')?.value.trim();if(!name){toast('表示名を入力してください。');return true;}try{localStorage.setItem('quantum-quest-online-name',name);}catch{}
   onlineAction('join',{seat:+id,name});return true;
  }
  case 'online-start':onlineAction('start');return true;
  case 'online-leave':onlineAction('leave');return true;
  case 'end':if(canAct())onlineAction('end');return true;
  case 'resolve-event':if(game?.notice?.actor===game.human)onlineAction('choice',{optionId:document.querySelector('#effect-choice')?.value});return true;
  case 'do-exchange':if(canAct())onlineAction('exchange',{from:document.querySelector('#exchange-from').value,to:document.querySelector('#exchange-to').value});return true;
  case 'offer-trade':if(canAct())onlineAction('offer',{other:+document.querySelector('#trade-partner').value,from:document.querySelector('#trade-from').value,to:document.querySelector('#trade-to').value});return true;
  case 'online-accept':onlineAction('accept-trade');return true;
  case 'online-decline':onlineAction('decline-trade');return true;
  case 'online-cancel-trade':onlineAction('cancel-trade');return true;
  case 'finish':if(!onlineRoom.isHost){toast('卓を終了できるのはホストです。');return true;}return false;
  case 'confirm-finish':if(onlineRoom.isHost)onlineAction('finish');return true;
  case 'new':case 'confirm-new':case 'tutorial-start':case 'tutorial-restart':case 'mode':return true;
  case 'accept-trade':case 'decline-trade':return true;
 }
 return false;
}

if(!SINGLE_PLAYER_ONLY&&window.location){const invited=new URL(window.location.href).searchParams.get('room');if(invited)openOnline(invited);}
